{
  "county_id": "HVA06",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "Satakunta wellbeing services county has age-standardised cancer mortality ratio 1.097, 9.7% above the national level, and the earliest measurable stage where it is clearly worse is referral into specialist care, with 3% of referrals processed after more than 21 days against 1 nationally.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended cervical cancer screening.",
      "rationale": "Cervical screening participation in Satakunta wellbeing services county is 72.1% against the 80% national target, and HPV self-sampling kits for non-attenders are expected to add 1.5-4.5 percentage points, closing about 38% of the gap.",
      "owner_role": "Wellbeing services county screening unit.",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders for colorectal screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in Satakunta wellbeing services county is 74.4% against the 80% national target, and reminder and multilingual re-invitation is expected to add 1.5-4.5 percentage points, closing about 53% of the gap.",
      "owner_role": "Wellbeing services county screening unit.",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that any of these actions will reduce cancer mortality in Satakunta wellbeing services county, because the mortality estimates are model scenarios under stated assumptions, the Danish pathway evidence is before/after without a control group, and no Finnish effect size exists for colorectal screening reminders."
}

